from escritura_base import unidad as U, iglesia as I, pregunta as P, modulo

SE7 = modulo("se-7", "Sagrada Escritura VII: Exégesis A.T. III: Sapienciales", "Salmos, Proverbios, Job, Eclesiastés, Cantar, Sabiduría y Eclesiástico",
 "Estudio de los libros sapienciales y poéticos: la sabiduría en Israel, los Salmos como oración, Proverbios y Eclesiástico, las preguntas de Job y Eclesiastés, y el Cantar de los Cantares y Sabiduría. 5 unidades de 90 minutos, un taller de cierre y una evaluación.",
 "Los libros sapienciales hablan de la vida cotidiana: el trabajo, la familia, el amor, el sufrimiento, la muerte. Y lo hacen con poesía. Son una escuela para aprender a vivir con sabiduría y a rezar con todo el corazón.",
 "Cada participante compone un salmo propio siguiendo un modelo bíblico (alabanza, súplica o acción de gracias), usando el paralelismo hebreo, y elige un proverbio bíblico para explicar a jóvenes con un ejemplo actual. Se comparten en un momento de oración final.",
 [
  U("La sabiduría en Israel",
    "Conocer qué es la literatura sapiencial, sus libros y sus rasgos principales.",
    "Además de la Ley y los Profetas, Israel cultivó la sabiduría: la reflexión sobre la vida a partir de la experiencia, en diálogo con otros pueblos. Los libros sapienciales son la parte más universal y cotidiana de la Biblia.",
    [("Los libros", "Se consideran sapienciales **Job, Proverbios, Eclesiastés (Qohélet), Sabiduría y Eclesiástico (Sirácida)**. Suelen agruparse con ellos los **Salmos** y el **Cantar de los Cantares**, por su carácter poético. Sabiduría y Eclesiástico son deuterocanónicos."),
     ("Una sabiduría práctica", "La sabiduría bíblica no es acumular conocimientos: es **saber vivir bien** ante Dios y ante los demás. Observa la naturaleza, la familia, el trabajo, el uso de la lengua, el dinero, y saca enseñanzas. Su principio es: «El temor del Señor es el principio de la sabiduría» (Proverbios 1,7), es decir, el respeto confiado a Dios."),
     ("Diálogo con otros pueblos", "Egipto y Mesopotamia también tenían literatura sapiencial, y algunos proverbios bíblicos se parecen a textos egipcios. Israel asumió esa sabiduría humana y la integró en su fe en el Dios único. La Biblia muestra que la verdad humana tiene lugar en la revelación."),
     ("La Sabiduría personificada", "En Proverbios 8 y en Sabiduría 7–9, la Sabiduría aparece como una figura que estaba junto a Dios en la creación y que invita a los seres humanos a su mesa. El Nuevo Testamento usará este lenguaje para hablar de Cristo, Palabra y Sabiduría de Dios (Juan 1; 1 Corintios 1,24; Colosenses 1,15-17).")],
    ("Proverbios 8,22-31 · La Sabiduría junto a Dios", "La Sabiduría dice que el Señor la creó al principio, antes que la tierra; estaba a su lado como arquitecto, jugando ante él todo el tiempo y deleitándose con los hijos de los hombres. Este texto prepara la fe cristiana en el Verbo, por quien todo fue hecho."),
    [I("Catecismo de la Iglesia Católica 216 y 295", "Dios creó el mundo según su sabiduría; la creación no es fruto de una necesidad ni del azar, sino de la libre voluntad de Dios."),
     I("Dei Verbum 15", "Los libros del Antiguo Testamento contienen una viva conciencia de Dios, sabia doctrina sobre la vida humana y tesoros admirables de oración.")],
    ["¿A quién consideras una persona sabia? ¿Por qué?", "¿Qué diferencia hay entre saber mucho y ser sabio?", "¿Qué te dice que la Biblia integre sabiduría de otros pueblos?", "¿Cómo relacionas la Sabiduría personificada con Jesús?"],
    "Cada participante trae un consejo de vida que haya recibido de un mayor. En grupos, busquen en Proverbios un texto que diga algo parecido y comparen.",
    "Señor, fuente de toda sabiduría: dame un corazón sabio y dócil, que aprenda de la vida, de los mayores y de tu Palabra. Que el respeto confiado a ti sea el principio de todas mis decisiones. Amén.",
    "Escribe el mejor consejo de vida que te han dado.",
    ["Nombrar los libros sapienciales.", "Comprender el carácter práctico de la sabiduría bíblica.", "Relacionar la Sabiduría personificada con Cristo."],
    ("El temor de Dios", "En la Biblia, el «temor de Dios» no es miedo, sino reverencia y confianza: reconocer que Dios es Dios. Es también uno de los dones del Espíritu Santo."),
    ("Sabiduría de abuela", "En la catequesis, un niño dice que su abuela siempre dice refranes. El catequista quiere aprovecharlo.", ["¿Cómo podría conectar los refranes con Proverbios?", "¿Qué actividad propondrías?"]),
    [["Sapiencial", "Relativo a la sabiduría práctica para la vida."], ["Temor de Dios", "Reverencia confiada ante Dios."], ["Sabiduría personificada", "La Sabiduría presentada como figura junto a Dios."]],
    ["El temor del Señor es el principio de la sabiduría. ¿Dónde necesitas sabiduría?", "Pide el don de sabiduría.", "Lee un capítulo de Proverbios cada día esta semana."],
    ["Traigan los consejos.", "Busquen en Proverbios.", "Comparen.", "Compartan."],
    "La sabiduría bíblica es saber vivir bien ante Dios."),
  U("Los Salmos: la oración de Israel y de la Iglesia",
    "Conocer la estructura, los géneros y el uso de los Salmos, y aprender a rezar con ellos.",
    "Los Salmos son 150 oraciones que Israel rezó durante siglos y que Jesús rezó, incluso en la cruz. La Iglesia los reza cada día en la Liturgia de las Horas. En ellos cabe toda la vida humana: alegría, angustia, gratitud, rabia, confianza.",
    [("Un libro de oraciones", "El Salterio tiene **150 salmos** divididos en cinco libros, cada uno terminado con una alabanza (doxología). Muchos se atribuyen a David, como patrono de la oración de Israel, aunque fueron compuestos a lo largo de siglos. La numeración varía: la tradición griega y latina suele ir un número atrás desde el Salmo 10 hasta el 147."),
     ("Géneros", "- **Himnos de alabanza:** cantan la grandeza de Dios (Salmos 8, 104, 148).\n- **Súplicas:** personales o colectivas, en momentos de angustia (Salmos 22, 51, 130).\n- **Acción de gracias:** por una salvación recibida (Salmos 30, 116).\n- **Salmos reales y mesiánicos:** sobre el rey de Israel (Salmos 2, 110).\n- **Salmos de confianza:** (Salmos 23, 91).\n- **Salmos sapienciales:** (Salmos 1, 119)."),
     ("La poesía hebrea", "La poesía hebrea no se basa en la rima, sino en el **paralelismo**: un verso repite, contrasta o completa al anterior. Por ejemplo: «Los cielos cuentan la gloria de Dios, / el firmamento anuncia la obra de sus manos» (Salmo 19,2). Conocerlo ayuda a leer y a rezar."),
     ("Rezar con los Salmos", "Los Salmos nos enseñan a decirle todo a Dios, incluso la queja y la rabia. Algunos salmos piden venganza: la Iglesia los lee como expresión del dolor de las víctimas que confían su causa a Dios. Rezarlos con Jesús, que los rezó, les da su sentido pleno.")],
    ("Salmo 22,2-12.23-25 · «Dios mío, Dios mío, ¿por qué me has abandonado?»", "Jesús reza en la cruz el comienzo de este salmo. Es la súplica de alguien que se siente abandonado, rodeado de enemigos, pero que termina alabando a Dios que escuchó su clamor. Rezar con los Salmos es aprender a llevar a Dios el dolor sin dejar de confiar."),
    [I("Catecismo de la Iglesia Católica 2585-2589", "Los Salmos son la obra maestra de la oración en el Antiguo Testamento; alimentan y expresan la oración del pueblo de Dios."),
     I("Verbum Domini 62", "La Liturgia de las Horas, con los Salmos, es una forma privilegiada de escucha de la Palabra de Dios.")],
    ["¿Qué salmo conoces de memoria o te gusta especialmente?", "¿Te atreves a decirle a Dios tu queja?", "¿Qué te dice que Jesús rezara un salmo en la cruz?", "¿Cómo usarías los Salmos en la pastoral juvenil?"],
    "En parejas, elijan un salmo de cada género (alabanza, súplica, acción de gracias). Identifiquen ejemplos de paralelismo y la estructura de cada uno. Luego récenlos juntos en voz alta.",
    "Señor, que pusiste en los Salmos todas las palabras del corazón humano: enséñame a rezar con ellos. Que te alabe en la alegría, te suplique en la angustia, te agradezca tus beneficios y confíe en ti como Jesús. Amén.",
    "Piensa en tu estado de ánimo de hoy. ¿Qué tipo de salmo necesitarías rezar?",
    ["Conocer la estructura del Salterio.", "Distinguir los géneros de los Salmos.", "Reconocer el paralelismo y rezar con los Salmos."],
    ("La numeración de los Salmos", "Las Biblias hebreas y la mayoría de las traducciones modernas usan una numeración; la liturgia latina antigua usaba otra, un número atrás en la mayoría de los salmos. Por eso algunas Biblias indican dos números (por ejemplo, Salmo 51 (50))."),
    ("El salmo de la venganza", "En un retiro, una joven que sufrió acoso lee el Salmo 58 y dice que siente que expresa lo que ella siente.", ["¿Cómo acompañarías ese momento?", "¿Qué enseña la Iglesia sobre estos salmos?"]),
    [["Salterio", "Libro de los Salmos."], ["Paralelismo", "Repetición o contraste entre versos de la poesía hebrea."], ["Liturgia de las Horas", "Oración de la Iglesia a lo largo del día, basada en los Salmos."]],
    ["Dios mío, ¿por qué me has abandonado? ¿Qué dolor le llevas a Dios?", "Reza un salmo cada día esta semana.", "Ofrece rezar un salmo con alguien que sufre."],
    ["Elijan los salmos.", "Identifiquen el paralelismo.", "Analicen la estructura.", "Récenlos."],
    "En los Salmos cabe toda la vida humana."),
  U("Proverbios y Eclesiástico: sabiduría para la vida cotidiana",
    "Conocer el mensaje de Proverbios y Eclesiástico sobre la vida diaria: la palabra, el trabajo, la familia, la amistad y el dinero.",
    "Proverbios y Eclesiástico son colecciones de consejos para la vida diaria. Parecen sencillos, pero condensan siglos de experiencia. Son un tesoro para la formación de jóvenes.",
    [("Proverbios", "Reúne colecciones de dichos atribuidas a Salomón y a otros sabios. Comienza con una invitación a escuchar la sabiduría (1–9) y sigue con cientos de sentencias breves. Termina con el elogio de la mujer fuerte (31,10-31), sabia, trabajadora y generosa."),
     ("Eclesiástico", "Escrito por **Jesús ben Sira** en Jerusalén, hacia el año 180 antes de Cristo, en hebreo, y traducido al griego por su nieto. Une la sabiduría práctica con la fidelidad a la Ley y al Templo, en un tiempo de influencia griega. Incluye un elogio de los antepasados de Israel (44–50)."),
     ("Temas para la vida", "- **La lengua:** «La respuesta suave calma el enojo» (Proverbios 15,1).\n- **El trabajo:** contra la pereza (Proverbios 6,6-11, la hormiga).\n- **La amistad:** «Un amigo fiel es un refugio seguro» (Eclesiástico 6,14).\n- **La familia:** respeto a los padres (Eclesiástico 3).\n- **El dinero:** compartir con el pobre (Proverbios 19,17)."),
     ("La sabiduría que se pide", "Los sabios no solo enseñan técnicas: invitan a **pedir** sabiduría a Dios y a aprender con humildad, aceptando la corrección. «El que ama la corrección ama el saber» (Proverbios 12,1).")],
    ("Eclesiástico 6,5-17 · El amigo fiel", "Ben Sira aconseja ser prudente al elegir amigos: hay amigos de ocasión que desaparecen en la desgracia. Pero «un amigo fiel es un refugio seguro: el que lo encuentra ha encontrado un tesoro». Y concluye que quien teme al Señor encontrará amigos como él."),
    [I("Catecismo de la Iglesia Católica 2214-2218", "El respeto a los padres, que la sabiduría bíblica enseña, nace de la gratitud hacia quienes nos dieron la vida."),
     I("Verbum Domini 86-87", "La lectura orante de la Escritura forma la sabiduría del creyente para la vida diaria.")],
    ["¿Qué proverbio te gustaría aplicar esta semana?", "¿Qué dice Ben Sira de tus amistades?", "¿Cómo recibes la corrección?", "¿Qué temas de Proverbios son urgentes para los jóvenes?"],
    "En grupos, armen un «manual de sabiduría para jóvenes» con diez proverbios bíblicos sobre temas actuales (redes sociales, amistad, estudio, dinero, familia), cada uno con un ejemplo concreto.",
    "Señor, que inspiraste a los sabios de Israel: dame una lengua que calme, manos que trabajen, amigos fieles y un corazón que acepte la corrección. Que mi vida diaria sea sabia ante ti. Amén.",
    "Elige un tema de tu vida diaria donde necesitas más sabiduría.",
    ["Conocer el contenido de Proverbios y Eclesiástico.", "Relacionar sus enseñanzas con la vida diaria.", "Usar los proverbios en la pastoral juvenil."],
    ("La mujer fuerte", "Proverbios 31 presenta a una mujer que administra, comercia, cuida, enseña y ayuda al pobre. Es una figura de la sabiduría encarnada en la vida cotidiana, lejos de la imagen de una mujer pasiva."),
    ("El grupo de WhatsApp", "En el grupo juvenil, un comentario en el chat genera una pelea que dura días.", ["¿Qué proverbios sobre la lengua podrían ayudar?", "¿Cómo los usarías sin moralizar?"]),
    [["Ben Sira", "Autor del Eclesiástico."], ["Sentencia", "Dicho breve de sabiduría."], ["Corrección", "Enseñanza que ayuda a crecer."]],
    ["Un amigo fiel es un tesoro. ¿Para quién eres amigo fiel?", "Agradece por tus amigos.", "Cuida tus palabras esta semana."],
    ["Elijan los temas.", "Busquen proverbios.", "Escriban ejemplos.", "Armen el manual."],
    "La sabiduría se juega en lo cotidiano."),
  U("Job y Eclesiastés: las preguntas difíciles",
    "Comprender cómo Job y Eclesiastés enfrentan el sufrimiento del justo y el sentido de la vida.",
    "No toda la Biblia da respuestas simples. Job y Eclesiastés se atreven a preguntar: ¿por qué sufre el inocente?, ¿qué sentido tiene todo si al final morimos? Son libros valientes que acompañan a quien atraviesa la duda.",
    [("Job: el sufrimiento del justo", "Job es un hombre justo que lo pierde todo: bienes, hijos y salud. Sus amigos le dicen que sufre por sus pecados, como pensaba la sabiduría tradicional. Job lo niega y discute con Dios. El libro rechaza la idea de que todo sufrimiento es castigo."),
     ("La respuesta de Dios", "Al final, Dios habla desde la tormenta (38–41), no con una explicación, sino mostrando la grandeza y el misterio de la creación. Job responde: «Te conocía solo de oídas, pero ahora te han visto mis ojos» (42,5). Dios le da la razón a Job frente a sus amigos: es mejor discutir con Dios con honestidad que defenderlo con mentiras."),
     ("Eclesiastés: todo es vanidad", "Qohélet observa la vida y concluye: «Vanidad de vanidades, todo es vanidad» (1,2). La palabra hebrea hebel significa vapor, soplo: todo es pasajero. Ni la riqueza ni el saber ni el placer dan sentido último. Hay «un tiempo para cada cosa» (3,1-8)."),
     ("Disfrutar con sencillez", "Eclesiastés no es un libro desesperado. Invita a disfrutar los dones sencillos de Dios: comer el pan con alegría, trabajar, amar, mientras se vive con humildad ante el misterio. Prepara la pregunta que el Nuevo Testamento responderá con la resurrección.")],
    ("Job 42,1-6 · Ahora te han visto mis ojos", "Después de escuchar a Dios, Job reconoce que habló de cosas que no comprendía. Dice: «Te conocía solo de oídas, pero ahora te han visto mis ojos». El sufrimiento no tuvo una explicación, pero sí un encuentro que transformó su fe."),
    [I("Catecismo de la Iglesia Católica 309-314", "No hay un rasgo del mensaje cristiano que no sea en parte una respuesta a la cuestión del mal; Dios permite el mal para sacar de él un bien mayor, aunque solo en el cielo lo conoceremos plenamente."),
     I("Catecismo de la Iglesia Católica 1500-1502", "La enfermedad y el sufrimiento han estado siempre entre los problemas más graves de la vida; en el Antiguo Testamento el ser humano vive su enfermedad en presencia de Dios, con quien se lamenta.")],
    ["¿Has escuchado decir que alguien sufre porque Dios lo castiga?", "¿Qué te dice que Dios le dé la razón a Job y no a sus amigos?", "¿Qué cosas de tu vida son «vapor»?", "¿Cómo acompañar a alguien que sufre sin dar respuestas fáciles?"],
    "Hagan un juego de roles: un participante es Job y otros son sus amigos. Luego otros participantes muestran cómo acompañarían a Job de una manera mejor. Conversen qué aprendieron.",
    "Señor, cuando el sufrimiento no tiene explicación, dame la honestidad de Job para hablarte. Cuando todo me parece vacío, dame la humildad de Qohélet para disfrutar tus dones sencillos. Y que un día pueda decir: ahora te han visto mis ojos. Amén.",
    "Escribe una pregunta difícil que le harías a Dios.",
    ["Comprender el mensaje del libro de Job.", "Conocer la reflexión de Eclesiastés.", "Acompañar el sufrimiento sin respuestas fáciles."],
    ("Los amigos de Job", "Los amigos de Job hacen algo bueno al comienzo: se sientan siete días en silencio junto a él (2,13). Lo malo empieza cuando quieren explicarle su dolor. A veces la mejor compañía es el silencio."),
    ("La explicación que duele", "En el funeral de un joven, alguien dice a la madre que «Dios necesitaba otro ángel».", ["¿Qué diría el libro de Job?", "¿Qué podrías decir o hacer tú?"]),
    [["Teología de la retribución", "Idea de que el bueno prospera y el malo sufre."], ["Hebel", "Vapor, soplo: lo pasajero."], ["Qohélet", "Nombre hebreo del Eclesiastés."]],
    ["Te conocía de oídas. ¿Conoces a Dios de oídas o por experiencia?", "Reza por quienes sufren sin explicación.", "Acompaña en silencio a alguien que lo está pasando mal."],
    ["Preparen los roles.", "Representen.", "Muestren otra forma.", "Conversen."],
    "Es mejor hablar honestamente con Dios que defenderlo con mentiras."),
  U("Cantar de los Cantares y Sabiduría: el amor y la vida inmortal",
    "Conocer el Cantar de los Cantares como poema del amor humano y el libro de la Sabiduría como puente hacia la esperanza en la vida eterna.",
    "El Cantar de los Cantares es un poema de amor entre un hombre y una mujer. El libro de la Sabiduría, el último del Antiguo Testamento en escribirse, habla de la inmortalidad. Ambos muestran lo más alto de la sabiduría bíblica: el amor y la vida que no termina.",
    [("El Cantar: el amor humano", "El Cantar es una colección de poemas donde dos enamorados se buscan, se alaban y se desean. Celebra el **amor humano** y la belleza del cuerpo como don de Dios. Dice: «El amor es fuerte como la muerte… las aguas torrenciales no pueden apagarlo» (8,6-7)."),
     ("El Cantar: lecturas espirituales", "La tradición judía lo leyó como imagen del amor entre Dios e Israel; los cristianos, como imagen del amor entre Cristo y la Iglesia o el alma. San Juan de la Cruz se inspiró en él. Ambas lecturas, la humana y la espiritual, son legítimas y se enriquecen."),
     ("Sabiduría: los justos están en manos de Dios", "Escrito en griego, probablemente en Alejandría en el siglo I antes de Cristo. Afirma: «Las almas de los justos están en las manos de Dios y ningún tormento los alcanzará» (3,1). Es uno de los textos del Antiguo Testamento que expresa con más claridad la esperanza en la vida después de la muerte."),
     ("Sabiduría: Dios ama la vida", "El libro dice que Dios no hizo la muerte ni se alegra con la perdición de los vivientes (1,13), y que ama todo lo que existe: «Tú amas a todos los seres y no aborreces nada de lo que hiciste… Señor que amas la vida» (11,24-26). Prepara la fe en la resurrección.")],
    ("Cantar de los Cantares 8,6-7 · El amor es fuerte como la muerte", "«Grábame como un sello sobre tu corazón… porque el amor es fuerte como la muerte». Las aguas no pueden apagarlo y no se compra con riquezas. Este texto se usa a menudo en los matrimonios y expresa la fuerza del amor que Dios puso en el corazón humano."),
    [I("Catecismo de la Iglesia Católica 1604 y 1611", "Dios, que creó al hombre por amor, lo llamó también al amor; los profetas y el Cantar expresan la alianza como un amor conyugal fiel."),
     I("Catecismo de la Iglesia Católica 992", "La resurrección de los muertos fue revelada progresivamente; la esperanza en la vida eterna se expresa en los últimos libros del Antiguo Testamento.")],
    ["¿Te sorprende que haya un poema de amor en la Biblia?", "¿Cómo hablarías del amor humano a jóvenes desde el Cantar?", "¿Qué te dice que «las almas de los justos están en las manos de Dios»?", "¿Cómo se relacionan el amor y la esperanza en la vida eterna?"],
    "En grupos, lean Cantar 2,8-17 y Sabiduría 3,1-9. Conversen cómo hablar del amor humano y de la muerte a jóvenes con lenguaje respetuoso, sin vergüenza y sin superficialidad. Preparen una catequesis breve.",
    "Dios que amas la vida y pusiste el amor en el corazón humano: gracias por el don del amor. Que ame con un amor fuerte como la muerte, y que confíe en que mi vida y la de los que amo está en tus manos para siempre. Amén.",
    "Escribe qué significa para ti un amor verdadero.",
    ["Comprender el Cantar como poema del amor humano y su lectura espiritual.", "Conocer la esperanza en la vida eterna del libro de la Sabiduría.", "Relacionar amor y esperanza en la pastoral juvenil."],
    ("La teología del cuerpo", "San Juan Pablo II dedicó muchas catequesis al amor humano y al cuerpo, comentando también el Cantar de los Cantares. Mostró que el cuerpo y la sexualidad son lenguaje del amor y del don de sí."),
    ("La risa nerviosa", "Al leer un texto del Cantar en el grupo, varios jóvenes se ríen nerviosos y otros se incomodan.", ["¿Cómo manejarías ese momento?", "¿Qué te ayudaría a presentar el texto con naturalidad?"]),
    [["Cantar de los Cantares", "Poema del amor entre un hombre y una mujer."], ["Lectura espiritual", "Lectura del Cantar como amor entre Dios y su pueblo."], ["Inmortalidad", "Esperanza en la vida más allá de la muerte."]],
    ["El amor es fuerte como la muerte. ¿A quién amas así?", "Reza por las parejas y los matrimonios que conoces.", "Expresa tu cariño a alguien de tu familia esta semana."],
    ["Lean los textos.", "Conversen.", "Preparen la catequesis.", "Presenten."],
    "Dios ama la vida y el amor es más fuerte que la muerte."),
 ],
 [P("¿Cuál es el principio de la sabiduría según Proverbios?", ["El conocimiento científico", "El temor del Señor", "La riqueza"], 1, "Proverbios 1,7."),
  P("¿En qué se basa la poesía hebrea?", ["En la rima", "En el paralelismo", "En la métrica griega"], 1, "Un verso repite, contrasta o completa al anterior."),
  P("¿Qué salmo rezó Jesús en la cruz?", ["Salmo 23", "Salmo 22", "Salmo 51"], 1, "«Dios mío, Dios mío, ¿por qué me has abandonado?»."),
  P("¿Quién escribió el Eclesiástico?", ["Salomón", "Jesús ben Sira", "Moisés"], 1, "Hacia el 180 antes de Cristo."),
  P("¿Qué rechaza el libro de Job?", ["Que Dios exista", "Que todo sufrimiento sea castigo por el pecado", "Que se pueda rezar"], 1, "Dios da la razón a Job frente a sus amigos."),
  P("¿Qué significa «vanidad» en Eclesiastés?", ["Orgullo", "Vapor, soplo, lo pasajero", "Belleza"], 1, "La palabra hebrea es hebel."),
  P("¿Qué celebra el Cantar de los Cantares?", ["Las victorias de Israel", "El amor humano entre un hombre y una mujer", "La Ley de Moisés"], 1, "Leído también como imagen del amor de Dios."),
  P("¿Qué afirma Sabiduría 3,1?", ["Que los justos desaparecen", "Que las almas de los justos están en las manos de Dios", "Que la muerte es el fin"], 1, "Prepara la fe en la resurrección."),
 ])

SE8 = modulo("se-8", "Sagrada Escritura VIII: Exégesis N.T. III: San Juan", "El cuarto evangelio y las cartas de Juan",
 "Estudio del evangelio de Juan y sus cartas: autor y comunidad, el prólogo y los signos, los discursos y los «Yo soy», la hora de la gloria y el mensaje de que Dios es amor. 5 unidades de 90 minutos, un taller de cierre y una evaluación.",
 "El evangelio de Juan es distinto de los sinópticos: más contemplativo, con largos diálogos y símbolos profundos. Lo llamaron el evangelio espiritual. En este módulo vas a aprender a leerlo para creer y tener vida.",
 "Cada participante prepara una lectio divina guiada de 20 minutos sobre un encuentro de Jesús en Juan (Nicodemo, la samaritana, el ciego de nacimiento, Marta y María, María Magdalena), con lectura, preguntas de meditación, momento de oración y compromiso. La guía con un grupo pequeño y recibe retroalimentación.",
 [
  U("El cuarto evangelio: autor, comunidad y propósito",
    "Conocer el origen, la estructura y el propósito del evangelio de Juan, y sus diferencias con los sinópticos.",
    "Juan dice claramente para qué escribió: «para que crean que Jesús es el Mesías, el Hijo de Dios, y creyendo tengan vida en su nombre» (20,31). En esta unidad vas a conocer su origen y su forma.",
    [("El discípulo amado", "El evangelio se atribuye a un testigo llamado «**el discípulo que Jesús amaba**», que aparece en la Última Cena, al pie de la cruz y en el sepulcro. La tradición lo identificó con el apóstol Juan. Muchos estudiosos piensan que el evangelio es fruto de una comunidad que se formó en torno a ese testigo y que recibió su forma final hacia fines del siglo I."),
     ("Diferencias con los sinópticos", "- Jesús va varias veces a **Jerusalén**; su ministerio parece durar unos tres años (tres Pascuas).\n- En lugar de parábolas breves hay **largos discursos** y diálogos.\n- Los milagros se llaman **signos**.\n- Faltan episodios como la institución de la Eucaristía, que se reemplaza por el **lavatorio de los pies**.\n- Destaca la identidad divina de Jesús desde el comienzo."),
     ("Estructura", "- **Prólogo** (1,1-18).\n- **Libro de los signos** (1,19–12,50): Jesús se revela con signos y discursos.\n- **Libro de la gloria** (13–20): la hora de Jesús, su pasión, muerte y resurrección.\n- **Epílogo** (21): aparición junto al lago y misión de Pedro."),
     ("Un lenguaje simbólico", "Juan usa símbolos con dos niveles de sentido: agua, luz, pan, vida, noche, ver, creer. Los personajes muchas veces entienden mal a Jesús (Nicodemo piensa que debe volver al vientre de su madre). El lector está invitado a pasar del sentido material al espiritual.")],
    ("Juan 20,30-31 · Para que crean y tengan vida", "Juan reconoce que Jesús hizo muchos otros signos que no están escritos. Estos fueron escritos para que crean que Jesús es el Mesías, el Hijo de Dios, y creyendo tengan vida en su nombre. Todo el evangelio es una invitación a creer."),
    [I("Dei Verbum 19", "Los evangelistas escribieron los cuatro evangelios con la intención de que conozcamos la verdad de lo que nos han enseñado."),
     I("Catecismo de la Iglesia Católica 514-515", "Los evangelios fueron escritos por hombres que se contaron entre los primeros que tuvieron fe y quisieron compartirla.")],
    ["¿Qué diferencias notas entre Juan y los sinópticos?", "¿Qué te dice que el autor se llame a sí mismo «el discípulo amado»?", "¿Qué símbolo de Juan te atrae más?", "¿Qué significa «creer y tener vida»?"],
    "Comparen la expulsión de los vendedores del Templo en Juan 2,13-22 y en Marcos 11,15-19: ubicación en el evangelio, detalles y significado. Conversen por qué Juan lo pone al comienzo.",
    "Señor Jesús, que llamaste discípulo amado a quien reclinó la cabeza en tu pecho: quiero ser también tu discípulo amado. Que al leer el evangelio de Juan crea más en ti y tenga vida en tu nombre. Amén.",
    "Escribe qué significa para ti «tener vida en abundancia».",
    ["Conocer el origen y el propósito del evangelio de Juan.", "Distinguirlo de los sinópticos.", "Reconocer su estructura y su lenguaje simbólico."],
    ("El evangelio espiritual", "Clemente de Alejandría, en el siglo II, llamó a Juan el «evangelio espiritual», porque, conociendo los otros, profundizó en el sentido interior de los hechos de Jesús."),
    ("«Juan inventó cosas»", "Un participante dice que Juan no es confiable porque cuenta cosas distintas que los otros.", ["¿Cómo explicarías el estilo de Juan?", "¿Qué aporta su mirada?"]),
    [["Discípulo amado", "Testigo al que se atribuye el cuarto evangelio."], ["Signos", "Nombre de los milagros en Juan."], ["Libro de la gloria", "Juan 13–20, la hora de Jesús."]],
    ["Para que crean y tengan vida. ¿Qué te falta para creer más?", "Pide la fe del discípulo amado.", "Lee esta semana Juan 1–4."],
    ["Lean los dos textos.", "Comparen.", "Interpreten.", "Compartan."],
    "Juan escribió para que creamos y tengamos vida."),
  U("El prólogo y los signos",
    "Comprender el prólogo de Juan y el sentido de los siete signos del libro de los signos.",
    "El evangelio de Juan comienza como el Génesis: «En el principio». El prólogo es un himno que presenta a Jesús como la Palabra eterna de Dios hecha carne. Luego, siete signos van revelando quién es.",
    [("En el principio era la Palabra", "El prólogo (1,1-18) afirma que la **Palabra** (en griego, Logos) existía desde el principio junto a Dios y era Dios; que por ella todo fue hecho; que es vida y luz; que vino a los suyos y no la recibieron; y que **«la Palabra se hizo carne y habitó entre nosotros»** (1,14). A los que la reciben les da poder de ser hijos de Dios."),
     ("Los siete signos", "Juan narra siete signos en la primera parte:\n\n1. Agua convertida en vino en Caná (2).\n2. Curación del hijo de un funcionario (4).\n3. Curación del paralítico en Betesda (5).\n4. Multiplicación de los panes (6).\n5. Jesús camina sobre el agua (6).\n6. Curación del ciego de nacimiento (9).\n7. Resurrección de Lázaro (11)."),
     ("Qué es un signo", "Un **signo** no es solo un hecho extraordinario: es una señal que remite a algo más profundo, a la identidad de Jesús. El agua convertida en vino revela que llega la alegría de la alianza nueva; el pan, que Jesús es el pan de vida; la curación del ciego, que es la luz del mundo; Lázaro, que es la resurrección."),
     ("Encuentros que transforman", "Juan presenta encuentros personales con Jesús: **Nicodemo** (3), que viene de noche; la **samaritana** (4), que se convierte en misionera; el **ciego de nacimiento** (9), que pasa de no ver a creer. Cada uno es un camino de fe que el lector puede recorrer.")],
    ("Juan 2,1-11 · Las bodas de Caná", "En una boda falta el vino. María le dice a Jesús y luego a los sirvientes: «Hagan todo lo que él les diga». Jesús convierte el agua en vino abundante y bueno. Es el primero de sus signos: manifestó su gloria y sus discípulos creyeron en él."),
    [I("Catecismo de la Iglesia Católica 456-460", "El Verbo se encarnó para salvarnos, para que conociésemos el amor de Dios, para ser nuestro modelo y para hacernos partícipes de la naturaleza divina."),
     I("Catecismo de la Iglesia Católica 547-549", "Jesús acompaña sus palabras con signos que manifiestan que el Reino está presente en él y atestiguan que es el Mesías.")],
    ["¿Qué te dice que la Palabra se haya hecho carne?", "¿Qué «vino» falta hoy en tu vida o comunidad?", "¿Qué signo de Juan te habla más?", "¿Con cuál de los personajes que se encuentran con Jesús te identificas?"],
    "En grupos, cada uno toma un signo, lo lee y responde: ¿qué hace Jesús?, ¿qué revela de él?, ¿cómo reaccionan los personajes?, ¿qué invita a creer? Presentan en cinco minutos.",
    "Palabra eterna del Padre, que te hiciste carne y habitaste entre nosotros: quiero recibirte. Transforma el agua de mi vida en vino de alegría, abre mis ojos como al ciego y llámame a la vida como a Lázaro. Amén.",
    "Escribe un momento en que sentiste que Jesús «convirtió el agua en vino» en tu vida.",
    ["Explicar el prólogo de Juan.", "Conocer los siete signos.", "Comprender el sentido de signo en Juan."],
    ("La Navidad y el prólogo", "El prólogo de Juan se lee en la misa del día de Navidad. Mientras Lucas cuenta el nacimiento en Belén, Juan contempla su sentido: la Palabra eterna se hizo carne."),
    ("«¿Por qué Jesús no hace milagros hoy?»", "Un adolescente pregunta en la catequesis por qué Jesús no hace hoy milagros como en el evangelio.", ["¿Qué enseña el concepto de signo?", "¿Dónde podemos ver hoy signos de Dios?"]),
    [["Logos", "Palabra; nombre de Jesús en el prólogo."], ["Encarnación", "La Palabra se hizo carne."], ["Signo", "Hecho que revela la identidad de Jesús."]],
    ["La Palabra se hizo carne. ¿Dónde se hace carne hoy?", "Reza el prólogo de Juan lentamente.", "Haz lo que Jesús te diga, como pidió María."],
    ["Elijan un signo.", "Respondan las preguntas.", "Preparen la presentación.", "Presenten."],
    "Los signos revelan quién es Jesús para que creamos."),
  U("Los discursos y los «Yo soy»",
    "Conocer los grandes discursos de Jesús en Juan y las afirmaciones «Yo soy».",
    "En Juan, Jesús habla mucho de sí mismo. Usa la expresión «Yo soy», que evoca el nombre de Dios revelado a Moisés. Sus discursos invitan a una relación personal con él.",
    [("Los «Yo soy» con imagen", "Jesús dice:\n\n- «Yo soy el **pan de vida**» (6,35).\n- «Yo soy la **luz del mundo**» (8,12).\n- «Yo soy la **puerta**» (10,9).\n- «Yo soy el **buen pastor**» (10,11).\n- «Yo soy la **resurrección y la vida**» (11,25).\n- «Yo soy el **camino, la verdad y la vida**» (14,6).\n- «Yo soy la **vid verdadera**» (15,1)."),
     ("El «Yo soy» absoluto", "En algunos pasajes Jesús dice simplemente «Yo soy», sin complemento: «Antes que Abraham existiera, Yo soy» (8,58). Evoca el nombre de Dios en Éxodo 3,14. Por eso sus oyentes quieren apedrearlo: entienden que se atribuye la identidad divina."),
     ("El discurso del pan de vida", "En el capítulo 6, después de multiplicar los panes, Jesús se presenta como el pan bajado del cielo: «El que come mi carne y bebe mi sangre tiene vida eterna». Muchos discípulos se van. Pedro dice: «Señor, ¿a quién iremos? Tú tienes palabras de vida eterna». La Iglesia lee este discurso en relación con la Eucaristía."),
     ("El discurso de despedida", "En la Última Cena (13–17), Jesús se despide: lava los pies, da el **mandamiento nuevo** («ámense como yo los he amado»), promete el **Espíritu Santo** Paráclito, se presenta como la vid y reza por la unidad de sus discípulos (capítulo 17).")],
    ("Juan 15,1-11 · Yo soy la vid", "Jesús es la vid verdadera y los discípulos, los sarmientos. El que permanece en él da mucho fruto, porque sin él no pueden hacer nada. Les dice esto para que su alegría esté en ellos y sea plena. Permanecer en Jesús es el secreto de toda vida cristiana y de todo servicio pastoral."),
    [I("Catecismo de la Iglesia Católica 589-590", "Jesús se atribuye prerrogativas divinas, como perdonar pecados, y al decir «Yo soy» revela su identidad divina."),
     I("Catecismo de la Iglesia Católica 1336 y 1406", "El discurso del pan de vida anuncia la Eucaristía: el que come este pan vivirá para siempre.")],
    ["¿Qué «Yo soy» necesitas escuchar hoy?", "¿Qué significa para ti «permanecer» en Jesús?", "¿Te has sentido alguna vez como los discípulos que se iban?", "¿Cómo vives el mandamiento nuevo en tu servicio?"],
    "Cada participante elige un «Yo soy» y prepara una imagen o símbolo para presentarlo en una oración comunitaria: lectura del texto, el símbolo y una frase personal.",
    "Señor Jesús, tú eres el pan, la luz, la puerta, el pastor, la resurrección, el camino y la vid. ¿A quién iremos? Solo tú tienes palabras de vida eterna. Quiero permanecer en ti y dar fruto. Amén.",
    "Completa: «Jesús, para mí tú eres…».",
    ["Conocer los «Yo soy» de Juan.", "Comprender el discurso del pan de vida.", "Conocer los temas del discurso de despedida."],
    ("El Paráclito", "Jesús llama al Espíritu Santo «Paráclito»: abogado, defensor, consolador, el que está al lado. Promete que estará siempre con los discípulos y les enseñará todo (14,16.26)."),
    ("El grupo que se queda sin gente", "Después de un retiro exigente, varios jóvenes dejan el grupo. Los dirigentes se preguntan si fueron demasiado exigentes.", ["¿Qué enseña Juan 6,60-69?", "¿Cómo discernir entre exigencia evangélica y dureza?"]),
    [["Yo soy", "Expresión con que Jesús revela su identidad."], ["Paráclito", "Nombre del Espíritu Santo en Juan."], ["Mandamiento nuevo", "Ámense como yo los he amado."]],
    ["Permanezcan en mi amor. ¿Qué te aleja de Jesús?", "Reza el capítulo 17 de Juan.", "Ama a alguien esta semana como Jesús te ama."],
    ["Elijan un «Yo soy».", "Preparen el símbolo.", "Organicen la oración.", "Recen juntos."],
    "Sin Jesús no podemos hacer nada; con él damos fruto."),
  U("El libro de la gloria: pasión y resurrección",
    "Comprender cómo presenta Juan la pasión, la muerte y la resurrección de Jesús como la hora de su glorificación.",
    "En Juan, la cruz no es solo sufrimiento: es la hora en que Jesús es glorificado, el momento en que muestra hasta dónde llega el amor. Su relato de la pasión tiene un tono distinto: Jesús es rey incluso en la cruz.",
    [("La hora", "Durante todo el evangelio se dice que «no había llegado su hora». En la Última Cena llega: «Sabiendo Jesús que había llegado su hora de pasar de este mundo al Padre, habiendo amado a los suyos, los amó hasta el extremo» (13,1). La hora es la cruz y la resurrección."),
     ("Un rey en la cruz", "En Juan, Jesús domina la escena: los soldados caen al suelo cuando dice «Yo soy» (18,6); ante Pilato habla de su reino que no es de este mundo; el letrero de la cruz está en tres lenguas. Jesús carga su cruz solo y muere diciendo «**Todo está cumplido**» (19,30)."),
     ("Al pie de la cruz", "Junto a la cruz están **María** y el **discípulo amado**. Jesús les dice: «Mujer, ahí tienes a tu hijo… ahí tienes a tu madre» (19,26-27). La tradición ve aquí a María como madre de la Iglesia. Del costado traspasado brotan **sangre y agua**, que los Padres leyeron como signo de la Eucaristía y el bautismo."),
     ("La resurrección", "**María Magdalena** va al sepulcro de madrugada y lo encuentra vacío. Pedro y el discípulo amado corren; el discípulo «vio y creyó». Jesús se aparece a María, que lo reconoce cuando la llama por su nombre, y la envía a anunciar. Luego se aparece a los discípulos, les da el Espíritu y la paz. **Tomás** pasa de la duda a la confesión: «¡Señor mío y Dios mío!» (20,28).")],
    ("Juan 20,11-18 · «¡María!»", "María Magdalena llora junto al sepulcro. Jesús le pregunta por qué llora; ella cree que es el jardinero. Cuando Jesús la llama por su nombre, lo reconoce: «¡Rabbuní!». Jesús la envía a anunciar a los discípulos. La tradición la llama «apóstol de los apóstoles»."),
    [I("Catecismo de la Iglesia Católica 640-644", "El sepulcro vacío y las apariciones del Resucitado a las mujeres y a los discípulos fundan la fe pascual."),
     I("Catecismo de la Iglesia Católica 964", "La unión de María con su Hijo se manifiesta al pie de la cruz, donde Jesús la dio como madre al discípulo.")],
    ["¿Qué te dice que Juan vea la cruz como gloria?", "¿Qué significa para ti que Jesús te dé a María como madre?", "¿Cuándo sentiste que Jesús te llamaba por tu nombre?", "¿Te identificas con Tomás?"],
    "Lean en voz alta, con distintos lectores, la pasión según Juan (18–19), como se hace el Viernes Santo. Después, en silencio, cada uno escribe la frase que más lo tocó y la comparte.",
    "Señor Jesús, que nos amaste hasta el extremo y en la cruz dijiste «todo está cumplido»: gracias por tu amor. Llámame por mi nombre como a María Magdalena y hazme testigo de tu resurrección. Señor mío y Dios mío. Amén.",
    "Escribe qué significa para ti «amar hasta el extremo».",
    ["Comprender la «hora» en Juan.", "Reconocer los rasgos propios de la pasión según Juan.", "Conocer los relatos de resurrección de Juan."],
    ("Viernes Santo", "La liturgia del Viernes Santo lee siempre la pasión según Juan, porque presenta la cruz como trono del Rey y fuente de vida."),
    ("La duda de Tomás", "Un joven confirmado dice que tiene muchas dudas de fe y que se siente mal por eso.", ["¿Qué aporta el relato de Tomás?", "¿Cómo lo acompañarías?"]),
    [["La hora", "Momento de la glorificación de Jesús en la cruz y la resurrección."], ["Todo está cumplido", "Últimas palabras de Jesús en Juan."], ["Apóstol de los apóstoles", "Título tradicional de María Magdalena."]],
    ["Los amó hasta el extremo. ¿Hasta dónde amas tú?", "Contempla un crucifijo en silencio.", "Anuncia esta semana la alegría de la resurrección a alguien."],
    ["Repartan los roles.", "Lean la pasión.", "Escriban la frase.", "Compartan."],
    "La cruz es la hora en que el amor llega al extremo."),
  U("Las cartas de Juan: Dios es amor",
    "Conocer el mensaje de las tres cartas de Juan, especialmente la primera, y su enseñanza sobre el amor.",
    "Las tres cartas de Juan nacen de la misma tradición que el evangelio. La primera contiene la definición más breve y profunda de Dios en toda la Biblia: «Dios es amor».",
    [("Una comunidad en crisis", "Las cartas reflejan una comunidad dividida: algunos se separaron y negaban que Jesús hubiera venido verdaderamente en la carne. El autor insiste en la fe en la encarnación y en el amor fraterno como señales de la verdadera comunión con Dios."),
     ("Dios es luz y Dios es amor", "La primera carta dice que «Dios es luz» (1,5) y que «**Dios es amor**» (4,8.16). Por eso, el que ama ha nacido de Dios y conoce a Dios; el que no ama no ha conocido a Dios. El amor no empieza en nosotros: «Él nos amó primero» (4,19)."),
     ("Amor concreto", "Juan es muy concreto: «Si alguien dice: amo a Dios, y no ama a su hermano, es un mentiroso» (4,20). «No amemos solo con palabras, sino con obras y de verdad» (3,18). Y si alguien tiene bienes y ve a su hermano necesitado y no lo ayuda, ¿cómo permanece en él el amor de Dios? (3,17)."),
     ("Las cartas breves", "La **segunda** y la **tercera** carta son muy breves, como notas personales. Hablan de caminar en la verdad, de la hospitalidad con los misioneros y de un líder, Diótrefes, que buscaba el primer lugar y no recibía a los hermanos.")],
    ("1 Juan 4,7-12 · Dios es amor", "Amémonos unos a otros, porque el amor viene de Dios. El que no ama no ha conocido a Dios, porque Dios es amor. En esto consiste el amor: no en que nosotros hayamos amado a Dios, sino en que él nos amó y envió a su Hijo. Si nos amamos, Dios permanece en nosotros."),
    [I("Catecismo de la Iglesia Católica 221", "San Juan afirma que Dios es amor; el ser mismo de Dios es amor, y al enviar a su Hijo y al Espíritu revela su secreto más íntimo."),
     I("Catecismo de la Iglesia Católica 2822-2827", "La voluntad del Padre es que nos amemos unos a otros como Él nos ha amado.")],
    ["¿Qué cambia saber que Dios te amó primero?", "¿Dónde amas solo con palabras?", "¿Qué necesidad de un hermano estás viendo y no ayudas?", "¿Qué te dice la figura de Diótrefes sobre el liderazgo?"],
    "Cada participante escribe una carta breve, al estilo de 2 o 3 Juan, a alguien de su comunidad, agradeciendo su amor concreto o animándolo. Al final, se proponen un gesto de amor con obras para la semana.",
    "Dios, que eres amor y nos amaste primero: gracias por enviar a tu Hijo. Que no ame solo con palabras, sino con obras y de verdad. Que tu amor permanezca en mí y se note en cómo trato a mis hermanos. Amén.",
    "Escribe una forma concreta en que puedes amar con obras esta semana.",
    ["Conocer el contexto de las cartas de Juan.", "Comprender la afirmación «Dios es amor».", "Relacionar fe y amor concreto."],
    ("Deus caritas est", "La primera encíclica de Benedicto XVI (2005) toma su título de 1 Juan 4,16: Dios es amor. Reflexiona sobre el amor de Dios y sobre la caridad de la Iglesia."),
    ("El servicio sin amor", "Un dirigente organiza todo perfectamente, pero trata mal a los jóvenes y a sus compañeros.", ["¿Qué diría la primera carta de Juan?", "¿Cómo se lo dirías tú?"]),
    [["Dios es amor", "Afirmación central de 1 Juan 4,8.16."], ["Amor fraterno", "Amor entre los miembros de la comunidad."], ["Encarnación", "Jesús vino verdaderamente en la carne."]],
    ["Él nos amó primero. ¿Cómo has experimentado ese amor?", "Reza 1 Juan 4,7-12 cada noche.", "Ama con obras a alguien que lo necesita."],
    ["Escriban la carta.", "Compártanla.", "Propongan un gesto.", "Recen juntos."],
    "Dios es amor, y quien ama permanece en Dios."),
 ],
 [P("¿Para qué escribió Juan su evangelio, según 20,31?", ["Para contar la historia de Israel", "Para que crean que Jesús es el Mesías y tengan vida", "Para criticar a los sinópticos"], 1, "Todo el evangelio invita a creer."),
  P("¿Cómo se llama a los milagros en Juan?", ["Prodigios", "Signos", "Parábolas"], 1, "Remiten a la identidad de Jesús."),
  P("¿Cuál es el primer signo de Jesús en Juan?", ["La multiplicación de los panes", "El agua convertida en vino en Caná", "La resurrección de Lázaro"], 1, "Juan 2,1-11."),
  P("¿Qué evoca el «Yo soy» absoluto de Jesús?", ["El nombre de Dios revelado a Moisés", "Un título político", "Una parábola"], 0, "Éxodo 3,14."),
  P("¿Qué gesto narra Juan en la Última Cena en lugar de la institución de la Eucaristía?", ["La unción en Betania", "El lavatorio de los pies", "La traición de Judas"], 1, "Juan 13."),
  P("¿Cuáles son las últimas palabras de Jesús en Juan?", ["Padre, perdónalos", "Todo está cumplido", "En tus manos encomiendo mi espíritu"], 1, "Juan 19,30."),
  P("¿Qué confiesa Tomás ante Jesús resucitado?", ["Tú eres el Mesías", "Señor mío y Dios mío", "Rabbuní"], 1, "Juan 20,28."),
  P("¿Qué afirma 1 Juan 4,8?", ["Dios es luz", "Dios es amor", "Dios es juez"], 1, "La definición más breve de Dios en la Biblia."),
 ])

SE9 = modulo("se-9", "Sagrada Escritura IX: Exégesis N.T. IV: Hebreos y Apocalipsis", "Cristo sumo sacerdote y el Cordero vencedor",
 "Estudio de la Carta a los Hebreos y del Apocalipsis: Cristo sumo sacerdote de la nueva alianza, la fe que persevera, el género apocalíptico, el Cordero y la Iglesia perseguida, y la esperanza de un cielo nuevo y una tierra nueva. 5 unidades de 90 minutos, un taller de cierre y una evaluación.",
 "Hebreos y el Apocalipsis cierran el Nuevo Testamento. Son libros difíciles y muchas veces mal entendidos. En este módulo vas a aprender a leerlos con sus claves propias y a descubrir su mensaje de esperanza para comunidades cansadas o perseguidas.",
 "Cada participante elige un símbolo del Apocalipsis o una imagen de Hebreos (el sumo sacerdote, la nube de testigos, el Cordero, la mujer vestida de sol, la Jerusalén celestial) y prepara una explicación de cinco minutos para jóvenes: qué significa en su contexto, qué errores de interpretación hay que evitar y qué esperanza transmite hoy. Se presentan y se comentan.",
 [
  U("La Carta a los Hebreos: Cristo, sumo sacerdote",
    "Conocer el origen y el mensaje central de la Carta a los Hebreos: Cristo, sumo sacerdote misericordioso.",
    "Hebreos no parece una carta: es una gran homilía escrita para cristianos cansados, que extrañaban el culto del Templo o pensaban abandonar la fe. Su respuesta es mostrar a Cristo como el sumo sacerdote definitivo.",
    [("Autor y destinatarios", "La tradición la incluyó entre las cartas de Pablo, pero su estilo y su vocabulario son distintos. Ya en la Antigüedad se dudaba de su autor; Orígenes dijo: «Quién la escribió, solo Dios lo sabe». Probablemente se dirige a cristianos de origen judío, desanimados, en la segunda mitad del siglo I."),
     ("Una homilía", "El autor la llama «palabra de exhortación» (13,22). Alterna exposición y exhortación: explica quién es Cristo y luego invita a perseverar. Usa mucho el Antiguo Testamento, sobre todo los Salmos y el culto del Levítico."),
     ("Cristo, superior a todo", "Hebreos comienza: «Muchas veces y de muchos modos habló Dios antiguamente a nuestros padres por medio de los profetas; en estos últimos tiempos nos ha hablado por medio del Hijo» (1,1-2). Cristo es superior a los ángeles y a Moisés: es el Hijo."),
     ("Un sumo sacerdote que nos comprende", "Cristo es el **sumo sacerdote** de la nueva alianza, no por linaje sino por su entrega. Es sacerdote «según el orden de Melquisedec» (Salmo 110). Y es misericordioso: «No tenemos un sumo sacerdote incapaz de compadecerse de nuestras debilidades, sino que fue probado en todo como nosotros, excepto en el pecado» (4,15).")],
    ("Hebreos 4,14-16 · Acerquémonos con confianza", "Tenemos un gran sumo sacerdote, Jesús, el Hijo de Dios, que comprende nuestras debilidades porque fue probado en todo como nosotros, menos en el pecado. Por eso podemos acercarnos con confianza al trono de la gracia para recibir misericordia en el momento oportuno."),
    [I("Catecismo de la Iglesia Católica 1544-1545", "Cristo es el único sacerdote; todo lo que prefiguraba el sacerdocio de la antigua alianza encuentra su cumplimiento en él."),
     I("Catecismo de la Iglesia Católica 662", "Cristo, sumo sacerdote de los bienes futuros, entró en el santuario del cielo para interceder siempre por nosotros.")],
    ["¿Te has sentido alguna vez como los destinatarios de Hebreos, cansado en la fe?", "¿Qué te dice que Jesús fue probado en todo como nosotros?", "¿Qué significa para ti acercarte con confianza al trono de la gracia?", "¿Cómo acompañarías a un joven desanimado en la fe?"],
    "Lean Hebreos 1,1-4 y 4,14–5,10. Hagan una lista de los títulos y rasgos de Cristo que aparecen y conversen cuáles ayudarían a un joven desanimado.",
    "Jesús, sumo sacerdote misericordioso, que fuiste probado en todo como nosotros: me acerco con confianza a ti. Dame tu misericordia y tu fuerza cuando me canso en la fe. Amén.",
    "Escribe algo que te cansa en tu vida de fe o en tu servicio.",
    ["Conocer el origen y género de Hebreos.", "Comprender a Cristo como sumo sacerdote.", "Aplicar el mensaje de Hebreos al acompañamiento."],
    ("Melquisedec", "Melquisedec es un misterioso rey y sacerdote que bendice a Abraham con pan y vino (Génesis 14,18-20). Hebreos lo presenta como figura de Cristo, sacerdote para siempre. La plegaria eucarística I lo menciona."),
    ("El joven que quiere dejar todo", "Un dirigente de 19 años dice que está cansado y quiere dejar el grupo y la Iglesia.", ["¿Qué le diría la Carta a los Hebreos?", "¿Cómo lo acompañarías?"]),
    [["Sumo sacerdote", "Título de Cristo en Hebreos."], ["Melquisedec", "Rey y sacerdote figura de Cristo."], ["Palabra de exhortación", "Nombre que Hebreos se da a sí misma."]],
    ["Acerquémonos con confianza. ¿Qué te impide acercarte?", "Reza por los que están cansados en la fe.", "Escribe a alguien que se ha alejado del grupo."],
    ["Lean los textos.", "Hagan la lista.", "Conversen.", "Compartan."],
    "Tenemos un sumo sacerdote que nos comprende."),
  U("Hebreos: la nueva alianza y la fe que persevera",
    "Comprender la enseñanza de Hebreos sobre la nueva alianza y la fe perseverante, con la «nube de testigos».",
    "Hebreos muestra que el sacrificio de Cristo, ofrecido una vez para siempre, inaugura la nueva alianza anunciada por Jeremías. Y termina con una galería de testigos de la fe que nos animan a correr con perseverancia.",
    [("Una vez para siempre", "Los sacrificios antiguos se repetían cada año. Cristo, en cambio, entró una sola vez en el santuario con su propia sangre, obteniendo una redención eterna (9,11-14). Su ofrenda es definitiva. La Eucaristía no repite su sacrificio: lo hace presente."),
     ("La nueva alianza", "Hebreos cita completo Jeremías 31,31-34 (8,8-12): Cristo es mediador de una alianza nueva, escrita en los corazones. La primera alianza era sombra de los bienes futuros; en Cristo llega la realidad."),
     ("La fe", "El capítulo 11 define: «La fe es la garantía de los bienes que se esperan y la plena certeza de las realidades que no se ven» (11,1). Luego recorre la fe de Abel, Noé, Abraham, Sara, Moisés, Rahab y tantos otros que vivieron confiando en promesas que no vieron cumplidas."),
     ("Correr con perseverancia", "«Rodeados de una nube tan grande de testigos, corramos con perseverancia la carrera que se nos propone, fijos los ojos en Jesús, el que inicia y completa nuestra fe» (12,1-2). Las dificultades se presentan como corrección de un Padre que ama. La carta termina con exhortaciones prácticas: hospitalidad, cuidado de los presos, fidelidad, desprendimiento.")],
    ("Hebreos 12,1-3 · La nube de testigos", "Rodeados de tantos testigos de la fe, dejemos todo lo que nos estorba y corramos con perseverancia, con los ojos fijos en Jesús, que soportó la cruz. Piensen en él para no desanimarse. La fe es una carrera de resistencia, y no corremos solos."),
    [I("Catecismo de la Iglesia Católica 1366-1367", "La Eucaristía es sacrificio porque representa, hace presente, el sacrificio de la cruz; es un único y mismo sacrificio."),
     I("Catecismo de la Iglesia Católica 146 y 165", "Hebreos 11 hace el elogio de la fe de los antepasados; el ejemplo de los testigos de la fe nos ayuda a perseverar.")],
    ["¿Qué testigos de la fe forman tu «nube»?", "¿Qué te estorba en la carrera de la fe?", "¿Cómo explicarías que la misa no repite el sacrificio de Cristo?", "¿Qué exhortación práctica del capítulo 13 te desafía?"],
    "Cada participante escribe su propio «Hebreos 11»: una lista de cinco personas (de la Biblia, santos o de su vida) que fueron testigos de fe para él o ella, con una frase de cada uno. Lo comparten en una oración final.",
    "Jesús, que inicias y completas nuestra fe: rodeado de tantos testigos, quiero correr con perseverancia mirándote a ti. Quita de mí lo que me estorba y dame fuerza para no desanimarme. Amén.",
    "Escribe el nombre de una persona que fue testigo de fe para ti.",
    ["Comprender el sacrificio único de Cristo y la nueva alianza.", "Conocer la definición de fe de Hebreos 11.", "Relacionar la nube de testigos con la perseverancia."],
    ("Sombra y realidad", "Hebreos usa la imagen de la sombra y la realidad: el culto antiguo era sombra de lo que vendría; Cristo es la realidad. Esta lectura influyó mucho en la comprensión cristiana del Antiguo Testamento."),
    ("La carrera", "Un grupo de dirigentes está desanimado porque trabajan mucho y no ven frutos.", ["¿Qué les diría Hebreos 11–12?", "¿Qué testigos podrían recordarles?"]),
    [["Nueva alianza", "Alianza en Cristo, escrita en los corazones."], ["Una vez para siempre", "Carácter único del sacrificio de Cristo."], ["Nube de testigos", "Los creyentes que nos preceden."]],
    ["Fijos los ojos en Jesús. ¿Dónde están puestos tus ojos?", "Reza por tus testigos de fe.", "Agradece a alguien que fue testigo de fe para ti."],
    ["Escriban su lista.", "Elijan frases.", "Compártanla.", "Recen."],
    "No corremos solos: una nube de testigos nos acompaña."),
  U("El Apocalipsis: género y claves de lectura",
    "Conocer el género apocalíptico y las claves para leer el Apocalipsis sin caer en interpretaciones sensacionalistas.",
    "El Apocalipsis es probablemente el libro más malinterpretado de la Biblia. Muchos lo leen como un calendario del fin del mundo. En realidad es un mensaje de esperanza para comunidades perseguidas, escrito en un lenguaje simbólico propio de su época.",
    [("Revelación, no catástrofe", "**Apocalipsis** significa «revelación»: quitar el velo. No significa catástrofe. El libro revela el sentido de la historia desde Dios: aunque el mal parezca vencer, Cristo resucitado es el Señor de la historia."),
     ("Autor y contexto", "El autor se presenta como **Juan**, desterrado en la isla de Patmos por anunciar la Palabra (1,9). Se suele fechar hacia fines del siglo I, en tiempos del emperador Domiciano, cuando las comunidades de Asia Menor sufrían presiones para rendir culto al emperador."),
     ("Un lenguaje simbólico", "El Apocalipsis usa símbolos que sus lectores entendían:\n\n- **Números:** 7, plenitud; 12, el pueblo de Dios; 1.000, una gran cantidad; 3 y medio, un tiempo limitado.\n- **Colores:** blanco, victoria; rojo, violencia.\n- **Animales:** el Cordero, Cristo; las bestias, los poderes opresores.\n- **Babilonia:** la Roma imperial y todo poder que oprime.\n\nNo son códigos para adivinar el futuro, sino imágenes para interpretar el presente."),
     ("Errores frecuentes", "- **Calcular fechas** del fin del mundo: Jesús dijo que nadie conoce el día ni la hora.\n- **Identificar** a personajes actuales con las bestias.\n- **Leerlo con miedo:** es un libro de esperanza.\n- **Leerlo aislado:** está lleno de citas del Antiguo Testamento (Daniel, Ezequiel, Isaías, Éxodo).")],
    ("Apocalipsis 1,9-18 · «No temas: yo soy el Primero y el Último»", "Juan, desterrado en Patmos, ve a Cristo resucitado en medio de siete candelabros, con rasgos simbólicos de gloria. Cae como muerto, pero Cristo le pone la mano encima y le dice: «No temas. Yo soy el Primero y el Último, el que vive. Estuve muerto, y ahora vivo para siempre». Así comienza el libro: con un no temas."),
    [I("Catecismo de la Iglesia Católica 673-674", "Desde la Ascensión, la venida de Cristo en la gloria es inminente, aunque no nos toca conocer el tiempo ni el momento."),
     I("Catecismo de la Iglesia Católica 2853", "La victoria sobre el príncipe de este mundo se adquirió de una vez para siempre en la hora en que Jesús se entregó libremente a la muerte.")],
    ["¿Qué te enseñaron o qué escuchaste sobre el Apocalipsis?", "¿Por qué crees que da miedo a mucha gente?", "¿Qué te dice que empiece con «no temas»?", "¿Cómo responderías a quien anuncia fechas del fin del mundo?"],
    "Hagan un glosario de símbolos del Apocalipsis: busquen en grupos diez símbolos (números, colores, animales, ciudades) y su significado, con la cita donde aparecen y el texto del Antiguo Testamento que los inspira.",
    "Señor Jesús, Primero y Último, el que vive: cuando el mal parece vencer, recuérdame que tú eres el Señor de la historia. Quita mis miedos y dame la esperanza de tu victoria. Amén.",
    "Escribe una imagen o idea que asociabas al Apocalipsis antes de este módulo.",
    ["Explicar qué significa apocalipsis.", "Conocer el contexto del libro.", "Interpretar sus símbolos y evitar errores frecuentes."],
    ("El 666", "El número de la bestia (13,18) probablemente es un juego numérico de la época: en hebreo y griego las letras tenían valor numérico. Muchos estudiosos lo relacionan con el nombre del emperador Nerón. En cualquier caso, 6 es lo que no llega a 7, la imperfección: el poder que se cree divino y no lo es."),
    ("El video del fin del mundo", "Un joven comparte un video que asegura que los acontecimientos actuales cumplen el Apocalipsis y que el fin llegará pronto. Varios del grupo están asustados.", ["¿Qué claves de lectura les darías?", "¿Cómo transmitir la esperanza del libro?"]),
    [["Apocalipsis", "Revelación."], ["Patmos", "Isla donde Juan recibió las visiones."], ["Babilonia", "Símbolo de la Roma imperial y de todo poder opresor."]],
    ["No temas. ¿Qué miedo necesitas entregar?", "Reza por los cristianos perseguidos hoy.", "Responde con esperanza a una noticia que da miedo."],
    ["Elijan los símbolos.", "Busquen su significado.", "Ubiquen las citas.", "Armen el glosario."],
    "El Apocalipsis no es un calendario del miedo, sino una revelación de esperanza."),
  U("Apocalipsis: el Cordero y la Iglesia perseguida",
    "Conocer las cartas a las siete iglesias, la visión del trono y del Cordero, y el mensaje para la Iglesia en la prueba.",
    "El centro del Apocalipsis no es la bestia ni las catástrofes: es el Cordero, Cristo muerto y resucitado, que es el único capaz de abrir el libro de la historia. Y la Iglesia, aunque perseguida, es la comunidad que lo sigue.",
    [("Las cartas a las siete iglesias", "Los capítulos 2 y 3 contienen mensajes a siete comunidades de Asia Menor: Éfeso, Esmirna, Pérgamo, Tiatira, Sardes, Filadelfia y Laodicea. Reconocen lo bueno, denuncian lo que falla y animan a la fidelidad. A Éfeso: «Has abandonado tu primer amor». A Laodicea: «No eres ni frío ni caliente». Siete es número de plenitud: son mensajes para toda la Iglesia."),
     ("El trono y el Cordero", "En los capítulos 4 y 5, Juan ve el trono de Dios y un libro sellado que nadie puede abrir. Llora. Le anuncian que el León de Judá ha vencido, y aparece un **Cordero como degollado**, de pie. El vencedor es el que se entregó: muerto y resucitado. Toda la creación lo adora."),
     ("Sellos, trompetas y copas", "Las series de siete sellos, siete trompetas y siete copas presentan, con imágenes de la tradición profética, las fuerzas del mal en la historia: guerra, hambre, muerte, persecución. No son un calendario sucesivo, sino distintas maneras de decir que el mal tiene sus días contados y que Dios cuida a los suyos (los sellados)."),
     ("La mujer y el dragón", "En el capítulo 12, una mujer vestida de sol da a luz un hijo, y un dragón quiere devorarlo. La mujer representa al pueblo de Dios, y la tradición la ve también como María. El dragón es vencido. Las bestias del capítulo 13 representan los poderes que exigen adoración. La Iglesia está llamada a resistir con fidelidad, sin violencia, como el Cordero.")],
    ("Apocalipsis 5,6-14 · El Cordero degollado", "Juan ve un Cordero de pie, como degollado. Toma el libro y todos cantan un cántico nuevo: «Eres digno de tomar el libro y abrir sus sellos, porque fuiste degollado y con tu sangre compraste para Dios hombres de toda raza, lengua, pueblo y nación». La victoria de Dios pasa por la entrega del Cordero."),
    [I("Catecismo de la Iglesia Católica 1137-1139", "El Apocalipsis muestra la liturgia celestial: el Cordero inmolado y de pie, y la asamblea de toda la creación que lo celebra; nuestra liturgia participa de ella."),
     I("Catecismo de la Iglesia Católica 2853", "Cristo venció al maligno; la Iglesia, como la mujer perseguida por el dragón, es protegida por Dios.")],
    ["¿Qué carta de las siete iglesias le escribirías a tu comunidad?", "¿Qué te dice que el vencedor sea un Cordero degollado?", "¿Qué poderes exigen hoy «adoración»?", "¿Qué relación ves entre el Apocalipsis y la misa?"],
    "En grupos, escriban una «carta a la iglesia de…» dirigida a su propia comunidad, con la estructura de Apocalipsis 2–3: presentación de Cristo, lo que se reconoce, lo que se reprocha, la exhortación y la promesa al vencedor.",
    "Cordero de Dios, que fuiste degollado y estás de pie: eres digno de toda alabanza. Danos fidelidad en la prueba, recupera nuestro primer amor y haz que resistamos el mal sin violencia, como tú. Amén.",
    "Escribe algo que admiras de tu comunidad y algo que debería cambiar.",
    ["Conocer las cartas a las siete iglesias.", "Comprender la centralidad del Cordero.", "Interpretar las series de siete y los capítulos 12 y 13."],
    ("El Cordero en la misa", "En la misa cantamos «Cordero de Dios, que quitas el pecado del mundo» y el sacerdote dice «Dichosos los invitados a la cena del Cordero», frase tomada de Apocalipsis 19,9. Cada Eucaristía es participación en la liturgia del cielo."),
    ("La comunidad tibia", "En una parroquia todo funciona, pero nadie se entusiasma: «ni frío ni caliente».", ["¿Qué dice la carta a Laodicea?", "¿Qué podría reavivar el primer amor?"]),
    [["Cordero", "Cristo muerto y resucitado, centro del Apocalipsis."], ["Siete iglesias", "Comunidades de Asia Menor que representan a toda la Iglesia."], ["Dragón", "Símbolo del mal vencido por Dios."]],
    ["Has abandonado tu primer amor. ¿Cómo está tu primer amor?", "Canta o reza el «Cordero de Dios» con atención en la próxima misa.", "Haz un gesto que reavive tu entusiasmo en el servicio."],
    ["Elijan la estructura.", "Escriban la carta.", "Léanla.", "Comenten."],
    "El vencedor de la historia es el Cordero que se entregó."),
  U("Apocalipsis: cielo nuevo y tierra nueva",
    "Comprender la visión final del Apocalipsis: la caída de Babilonia, la Jerusalén celestial y la esperanza cristiana.",
    "El Apocalipsis no termina en destrucción, sino en una boda y una ciudad nueva. La última palabra de la Biblia es una invitación: «Ven, Señor Jesús». En esta unidad cerramos el diplomado con la gran esperanza cristiana.",
    [("La caída de Babilonia", "Los capítulos 17 y 18 describen la caída de Babilonia, la gran ciudad que se emborrachó con la sangre de los santos y se enriqueció con el comercio injusto. Es el fin de todo poder que oprime. El cielo canta: ¡Aleluya!"),
     ("Las bodas del Cordero", "En el capítulo 19 se anuncian las **bodas del Cordero** con su esposa, la Iglesia, vestida de lino blanco, que son las buenas obras de los santos. «Dichosos los invitados al banquete de bodas del Cordero» (19,9). El final de la historia es una fiesta de amor."),
     ("La Jerusalén nueva", "«Vi un cielo nuevo y una tierra nueva» (21,1). La ciudad santa baja del cielo, y Dios habita con los seres humanos: «Secará todas las lágrimas de sus ojos, y no habrá más muerte, ni llanto, ni gritos, ni dolor» (21,4). La ciudad no tiene templo, porque Dios y el Cordero son su templo. Junto a ella corre el río de agua de vida y crece el árbol de la vida, cuyas hojas sanan a las naciones."),
     ("«Ven, Señor Jesús»", "El libro termina con el Espíritu y la esposa que dicen: «Ven». Y Jesús responde: «Sí, vengo pronto». La Iglesia responde: «**Amén. Ven, Señor Jesús**» (22,20). La esperanza cristiana no es evasión: compromete a trabajar ya por un mundo según Dios, mientras esperamos su plenitud.")],
    ("Apocalipsis 21,1-7 · Todo lo hago nuevo", "Juan ve un cielo nuevo y una tierra nueva, y la ciudad santa que baja de Dios como una novia. Una voz dice que Dios habitará con su pueblo y secará sus lágrimas. El que está sentado en el trono dice: «Yo hago nuevas todas las cosas». Es la promesa final de la Biblia."),
    [I("Catecismo de la Iglesia Católica 1042-1050", "Al fin de los tiempos, el Reino de Dios llegará a su plenitud; el universo será renovado; la esperanza de cielos nuevos y tierra nueva no debe debilitar, sino avivar la preocupación por perfeccionar esta tierra."),
     I("Catecismo de la Iglesia Católica 2817", "La petición «venga tu Reino» se hace eco del «Ven, Señor Jesús» con que termina la Escritura.")],
    ["¿Qué lágrimas esperas que Dios seque?", "¿Qué «Babilonias» ves hoy?", "¿Cómo trabajar ya por un mundo nuevo mientras esperamos?", "¿Qué te deja este diplomado para tu servicio pastoral?"],
    "Para cerrar el diplomado, cada participante escribe una oración final con tres partes: lo que agradece de lo aprendido en la Escritura, lo que pide para su servicio y su «Ven, Señor Jesús». Se reza en una celebración de la Palabra con la lectura de Apocalipsis 21,1-7.",
    "Señor Jesús, que haces nuevas todas las cosas: gracias por tu Palabra, que me acompañó en este camino. Seca nuestras lágrimas, derriba toda Babilonia y haz que trabajemos por tu Reino mientras esperamos tu venida. Amén. Ven, Señor Jesús.",
    "Escribe algo que te gustaría ver «hecho nuevo» en tu vida o en el mundo.",
    ["Comprender la visión final del Apocalipsis.", "Relacionar la esperanza cristiana con el compromiso.", "Integrar el recorrido del diplomado."],
    ("De Génesis a Apocalipsis", "La Biblia empieza en un jardín con un árbol de la vida (Génesis 2) y termina en una ciudad con el árbol de la vida (Apocalipsis 22). Toda la historia de la salvación va del jardín perdido a la ciudad nueva donde Dios habita con su pueblo."),
    ("«El cielo es aburrido»", "Un joven dice que no le interesa el cielo porque se lo imagina como estar sentado en una nube cantando para siempre.", ["¿Qué imágenes del Apocalipsis ofrecerías?", "¿Cómo explicarías la vida eterna como plenitud?"]),
    [["Jerusalén celestial", "Imagen de la comunión plena con Dios."], ["Bodas del Cordero", "Unión definitiva de Cristo y su Iglesia."], ["Maranatha", "Ven, Señor (en arameo)."]],
    ["Yo hago nuevas todas las cosas. ¿Qué quieres que Dios renueve?", "Termina cada día de esta semana diciendo «Ven, Señor Jesús».", "Haz algo concreto por un mundo más justo."],
    ["Escriban la oración final.", "Preparen la celebración.", "Lean Apocalipsis 21.", "Recen juntos."],
    "La Biblia termina con una promesa: todo será hecho nuevo."),
 ],
 [P("¿Qué dijo Orígenes sobre el autor de Hebreos?", ["Que era Pablo", "Que solo Dios sabe quién la escribió", "Que era Juan"], 1, "Su autor es desconocido."),
  P("¿Cómo presenta Hebreos a Cristo?", ["Como un ángel", "Como sumo sacerdote misericordioso", "Como un profeta más"], 1, "Hebreos 4,14-16."),
  P("¿Qué define Hebreos 11,1?", ["La caridad", "La fe", "La esperanza"], 1, "La fe es garantía de lo que se espera."),
  P("¿Qué significa «apocalipsis»?", ["Catástrofe", "Revelación", "Fin del mundo"], 1, "Quitar el velo."),
  P("¿Qué representa Babilonia en el Apocalipsis?", ["Una ciudad del futuro", "La Roma imperial y todo poder opresor", "El cielo"], 1, "Es un símbolo."),
  P("¿Quién es el centro del Apocalipsis?", ["La bestia", "El Cordero, Cristo muerto y resucitado", "El dragón"], 1, "Apocalipsis 5."),
  P("¿Qué error se debe evitar al leer el Apocalipsis?", ["Leerlo con esperanza", "Calcular fechas del fin del mundo", "Relacionarlo con el Antiguo Testamento"], 1, "Nadie conoce el día ni la hora."),
  P("¿Con qué palabras termina la Biblia?", ["Amén. Ven, Señor Jesús", "En el principio", "Todo está cumplido"], 0, "Apocalipsis 22,20."),
 ])

MODULOS = [SE7, SE8, SE9]
